"""A small, lossless syntax reader for Nix expressions.

Positions refer to the original input, so diagnostics and source edits do not
need to reconstruct whitespace or comments from the tree.
"""
import re
from dataclasses import dataclass, field

@dataclass
class Token:
    kind: str
    text: str
    start: int
    end: int

@dataclass
class Node:
    kind: str
    start: int
    end: int
    children: list = field(default_factory=list)
    data: dict = field(default_factory=dict)
    parent: object = None

    def __post_init__(self):
        for c in self.children:
            if c is not None:
                c.parent = self

    def __getattr__(self, name):
        data = self.__dict__.get('data', {})
        if name in data:
            return data[name]
        raise AttributeError(name)

    def text(self, source):
        return source[self.start:self.end]

TOKEN_NAMES = {
    '(': 'L_PAREN', ')': 'R_PAREN', '{': 'L_BRACE', '}': 'R_BRACE',
    '[': 'L_BRACK', ']': 'R_BRACK', ';': 'SEMICOLON', ':': 'COLON',
    ',': 'COMMA', '.': 'DOT', '=': 'ASSIGN', '?': 'QUESTION', '@': 'AT',
    '...': 'ELLIPSIS', '==': 'EQUAL', '!=': 'NOT_EQUAL', '!': 'INVERT',
    '+': 'ADD', '-': 'SUB', '*': 'MUL', '/': 'DIV', '++': 'CONCAT',
    '//': 'UPDATE', '&&': 'AND_AND', '||': 'OR_OR', '->': 'IMPLICATION',
    '<': 'LESS', '>': 'MORE', '<=': 'LESS_OR_EQ', '>=': 'MORE_OR_EQ',
    'IDENT': 'IDENT', 'NUMBER': 'INTEGER', 'FLOAT': 'FLOAT',
    'STRING': 'STRING_START', 'URI': 'URI', 'PATH': 'PATH',
    '${': 'INTERPOL_START', 'UNKNOWN': 'ERROR'
}
KEYWORDS = {'let', 'in', 'rec', 'if', 'then', 'else', 'with', 'assert', 'inherit', 'or'}
EXPR_WANTED = ['L_PAREN', 'REC', 'L_BRACE', 'L_BRACK', 'STRING_START', 'IDENT']

class Lexer:
    def __init__(self, source, start=0, end=None):
        self.source = source
        self.start = start
        self.end = len(source) if end is None else end
        self.comments = []
        self.tokens = []
        self.scan()

    def scan_string(self, pos, indented=False):
        s, end = self.source, self.end
        quote = "''" if indented else '"'
        i = pos + len(quote)
        while i < end:
            if not indented and s[i] == '\\':
                i += 2
            elif s.startswith('${', i):
                i = self.interpolation_end(i + 2)
            elif indented and s.startswith("''", i):
                if i + 2 < end and s[i+2] in "'$\\":
                    i += 3
                    if s[i-1] == '\\': i += 1
                else:
                    return i + 2
            elif not indented and s[i] == '"':
                return i + 1
            else:
                i += 1
        return end

    def interpolation_end(self, pos):
        s, end, depth, i = self.source, self.end, 1, pos
        while i < end:
            if s[i] == '"' or s.startswith("''", i):
                i = self.scan_string(i, s.startswith("''", i))
            elif s.startswith('/*', i):
                n = s.find('*/', i+2); i = end if n < 0 else n+2
            elif s[i] == '#':
                n = s.find('\n', i); i = end if n < 0 else n+1
            elif s[i] == '{':
                depth += 1; i += 1
            elif s[i] == '}':
                depth -= 1; i += 1
                if depth == 0: return i
            else:
                i += 1
        return end

    def scan(self):
        s, i, end = self.source, self.start, self.end
        while i < end:
            start = i
            if s[i].isspace():
                i += 1
                while i < end and s[i].isspace(): i += 1
                continue
            if s[i] == '#':
                i = s.find('\n', i)
                if i < 0 or i > end: i = end
                self.comments.append((start, i)); continue
            if s.startswith('/*', i):
                close = s.find('*/', i+2)
                i = min(end, close+2) if close >= 0 else end
                self.comments.append((start, i)); continue
            if s[i] == '"' or s.startswith("''", i):
                i = self.scan_string(i, s.startswith("''", i))
                kind = 'STRING'
            elif s.startswith('${', i):
                kind = '${'; i += 2
            else:
                # URI tokens have priority over identifiers and colons.
                m = re.match(r"[A-Za-z][A-Za-z0-9+.-]*:[A-Za-z0-9%/?:@&=+$,_.!~*'\-]+", s[i:end])
                if m:
                    i += len(m.group()); kind = 'URI'
                else:
                    # A path must contain a slash.  Bare / is an operator.
                    m = re.match(r"(?:~?/|\.\.?/|[A-Za-z0-9._+\-]+/)[A-Za-z0-9._+\-/~]*", s[i:end])
                    if m and len(m.group()) > 1 and not s.startswith('//', i):
                        i += len(m.group()); kind = 'PATH'
                        # Interpolated path suffixes are still a single expression.
                        while i < end and s.startswith('${', i):
                            i = self.interpolation_end(i+2)
                            mm = re.match(r'[A-Za-z0-9._+\-/~]*', s[i:end]); i += len(mm.group())
                    elif s[i] == '<' and re.match(r'<[A-Za-z0-9._+\-/]+>', s[i:end]):
                        m = re.match(r'<[A-Za-z0-9._+\-/]+>', s[i:end]); i += len(m.group()); kind = 'PATH'
                    elif re.match(r'[A-Za-z_]', s[i]):
                        m = re.match(r"[A-Za-z_][A-Za-z0-9_'\-]*", s[i:end]); i += len(m.group())
                        kind = s[start:i] if s[start:i] in KEYWORDS else 'IDENT'
                    elif s[i].isdigit() or (s[i] == '.' and i+1 < end and s[i+1].isdigit()):
                        m = re.match(r'(?:[0-9]+\.[0-9]*|\.[0-9]+)(?:[eE][+-]?[0-9]+)?|[0-9]+', s[i:end])
                        if m:
                            i += len(m.group()); kind = 'FLOAT' if '.' in m.group() else 'NUMBER'
                        else:
                            i += 1; kind = 'UNKNOWN'
                    elif s.startswith('...', i):
                        i += 3; kind = '...'
                    elif s[i:i+2] in ('==','!=','<=','>=','&&','||','->','//','++'):
                        kind = s[i:i+2]; i += 2
                    else:
                        kind = s[i] if s[i] in '(){}[];:,.=?@+-*/!<>' else 'UNKNOWN'; i += 1
            self.tokens.append(Token(kind, s[start:i], start, i))
        self.tokens.append(Token('EOF', '', end, end))

class Parser:
    PRECEDENCE = {'->': 1, '||': 2, '&&': 3, '==': 4, '!=': 4,
                  '<': 5, '>': 5, '<=': 5, '>=': 5, '//': 6,
                  '+': 7, '-': 7, '*': 8, '/': 8, '++': 9, '?': 11}
    def __init__(self, source, start=0, end=None):
        self.source = source
        self.lex = Lexer(source, start, end)
        self.tokens = self.lex.tokens
        self.i = 0
        self.errors = []
        self.depth = 0

    def peek(self, n=0):
        return self.tokens[min(self.i+n, len(self.tokens)-1)]

    def pop(self):
        t = self.peek()
        if t.kind != 'EOF': self.i += 1
        return t

    def at(self, k): return self.peek().kind == k
    def eat(self, k): return self.pop() if self.at(k) else None

    def error(self, t=None, wanted=None):
        t = self.peek() if t is None else t
        if t.kind == 'EOF':
            msg = 'Unexpected end of file'
            pos, end = 0, 0
        else:
            name = TOKEN_NAMES.get(t.kind, t.kind.upper())
            a = len(self.source[:t.start].encode('utf-8'))
            b = len(self.source[:t.end].encode('utf-8'))
            msg = f'Unexpected TOKEN_{name} at {a}..{b}'
            pos, end = t.start, t.end
        if wanted:
            msg += ', wanted any of [' + ', '.join('TOKEN_'+w for w in wanted) + ']'
        self.errors.append((pos, end, msg))

    def expect(self, k):
        if self.at(k): return self.pop()
        names = [TOKEN_NAMES.get(k, k.upper())]
        if self.at('EOF'):
            self.error(wanted=names); return self.peek()
        # Recovery skips unexpected text until the requested punctuation.
        self.error(wanted=names)
        while not self.at(k) and not self.at('EOF'): self.pop()
        if self.at(k): return self.pop()
        self.error(wanted=names)
        return self.peek()

    def parse(self):
        node = self.expr()
        if not self.at('EOF'):
            t = self.peek()
            self.errors.append((t.start, self.tokens[-1].start, 'Unexpected extra tokens'))
        return Node('Root', 0, len(self.source), [node] if node else [])

    def expr(self, minp=0):
        self.depth += 1
        if self.depth > 300:
            self.depth -= 1
            self.error(); return None
        left = self.prefix()
        if left is None:
            self.depth -= 1
            return None
        while True:
            t = self.peek()
            if t.kind == '.' and 15 >= minp:
                self.pop()
                path = self.attrpath()
                children = [left, path]
                fallback = None
                if self.eat('or'):
                    fallback = self.expr(13)
                    if fallback: children.append(fallback)
                left = Node('Select', left.start, children[-1].end, children,
                            {'base': left, 'path': path, 'fallback': fallback})
                continue
            if self.starts_simple(t.kind) and 13 >= minp:
                right = self.expr(14)
                if not right: break
                left = Node('Apply', left.start, right.end, [left,right], {'func':left, 'arg':right})
                continue
            p = self.PRECEDENCE.get(t.kind, -1)
            if p < minp: break
            self.pop()
            if t.kind == '?':
                path = self.attrpath()
                left = Node('HasAttr', left.start, path.end, [left,path], {'base':left,'path':path})
                continue
            right = self.expr(p if t.kind in ('->','//','++') else p+1)
            if not right: break
            left = Node('Bin', left.start, right.end, [left,right], {'left':left,'right':right,'op':t.kind})
        self.depth -= 1
        return left

    @staticmethod
    def starts_simple(k):
        return k in ('IDENT','NUMBER','FLOAT','PATH','URI','STRING','(','[','{','rec')

    def prefix(self):
        t = self.peek()
        if t.kind == 'IDENT' and self.peek(1).kind == ':':
            self.pop(); self.pop()
            param = Node('Ident', t.start, t.end)
            body = self.expr()
            return Node('Lambda', t.start, body.end if body else t.end,
                        [x for x in (param,body) if x], {'param':param,'body':body})
        if t.kind == 'IDENT' and self.peek(1).kind == '@':
            self.pop(); self.pop()
            return self.pattern_lambda(t)
        if t.kind == '{' and self.is_pattern():
            return self.pattern_lambda()
        if t.kind == 'let':
            self.pop()
            if self.at('{'):
                return self.attrset('Legacy', t)
            entries = self.bindings('in')
            it = self.eat('in')
            if it is None:
                self.error(); it = self.peek()
            body = self.expr()
            return Node('Let', t.start, body.end if body else it.end,
                        entries + ([body] if body else []), {'entries':entries,'body':body,'in_token':it,'let_token':t})
        if t.kind == 'rec':
            self.pop(); return self.attrset('Set', t)
        if t.kind == '{': return self.attrset()
        if t.kind == 'if':
            self.pop(); cond = self.expr(); self.expect('then')
            yes = self.expr(); self.expect('else'); no = self.expr()
            children = [x for x in (cond,yes,no) if x]
            return Node('If', t.start, children[-1].end if children else t.end, children,
                        {'cond':cond,'yes':yes,'no':no})
        if t.kind in ('with','assert'):
            self.pop(); scope = self.expr(); self.expect(';'); body = self.expr()
            children = [x for x in (scope,body) if x]
            return Node(t.kind.title(),t.start,children[-1].end if children else t.end,children,{'scope':scope,'body':body})
        if t.kind in ('!', '-'):
            self.pop(); val = self.expr(10 if t.kind == '!' else 12)
            return Node('Unary',t.start,val.end if val else t.end,[val] if val else [], {'op':t.kind,'value':val})
        if t.kind == '(':
            self.pop(); inner = self.expr(); close = self.expect(')')
            return Node('Paren',t.start,close.end,[inner] if inner else [],{'inner':inner})
        if t.kind == '[':
            self.pop(); items = []
            while not self.at(']') and not self.at('EOF'):
                old = self.i
                item = self.expr(14)
                if item: items.append(item)
                if old == self.i: self.pop()
            if self.at('EOF'): self.error()
            close = self.pop()
            return Node('List', t.start, close.end, items, {'items':items})
        if t.kind in ('IDENT','NUMBER','FLOAT','PATH','URI','STRING'):
            self.pop()
            kind = {'IDENT':'Ident','NUMBER':'Literal','FLOAT':'Literal','PATH':'Literal','URI':'Uri','STRING':'String'}[t.kind]
            children = self.interpolations(t) if t.kind in ('STRING','PATH') else []
            return Node(kind,t.start,t.end,children, {'token_kind':t.kind})
        if t.kind == '${':
            self.pop(); inner = self.expr(); close = self.expect('}')
            return Node('Dynamic',t.start,close.end,[inner] if inner else [])
        if t.kind == 'EOF':
            self.error(); return None
        self.error(wanted=EXPR_WANTED); self.pop()
        return Node('Error',t.start,t.end)

    def interpolations(self, t):
        s = self.source
        children, i = [], t.start + (2 if s.startswith("''", t.start) else 1)
        while i < t.end:
            if s[i] == '\\': i += 2; continue
            if s.startswith("''$", i): i += 3; continue
            if s.startswith('${',i):
                end = self.lex.interpolation_end(i+2)
                p = Parser(s, i+2, min(end-1,t.end))
                n = p.expr()
                if n: children.append(n)
                self.errors.extend(p.errors)
                i = end
            else: i += 1
        return children

    def is_pattern(self):
        # Brace pairs are ambiguous until the closing brace and optional bind.
        depth, j = 0, self.i
        while j < len(self.tokens):
            t = self.tokens[j]
            if t.kind in ('{','${'): depth += 1
            elif t.kind == '}':
                depth -= 1
                if depth == 0:
                    return j+1 < len(self.tokens) and self.tokens[j+1].kind in (':','@')
            if t.kind == 'EOF': break
            j += 1
        return False

    def pattern_lambda(self, bind_token=None):
        brace = self.expect('{')
        start = bind_token.start if bind_token else brace.start
        entries = []
        children = []
        while not self.at('}') and not self.at('EOF'):
            if self.eat('...'):
                self.eat(','); continue
            if self.at('IDENT'):
                tok = self.pop(); ident = Node('Ident',tok.start,tok.end)
                default = None
                if self.eat('?'): default = self.expr()
                entry = Node('PatternEntry',tok.start,default.end if default else tok.end,
                             [ident]+([default] if default else []))
                entries.append(entry); children.append(entry)
            else:
                self.error(wanted=['IDENT']); self.pop()
            if self.at('}'): break
            if not self.eat(','):
                self.expect(',')
        if self.at('EOF'): self.error()
        close = self.pop()
        if self.eat('@'):
            bind_token = self.expect('IDENT')
            end = bind_token.end
        else: end = close.end
        pat = Node('Pattern',start,end,children, {'entries':entries, 'bind':bind_token.text if bind_token else None})
        self.expect(':'); body = self.expr()
