"""Configuration and file selection, without third-party dependencies."""
import fnmatch
import json
import os
import re
from pathlib import Path

class ConfigError(Exception): pass

class TomlReader:
    def __init__(self, text):
        self.text = text
        self.i = 0
        self.section = ''
        self.data = {}

    def location(self, pos):
        return self.text.count('\n',0,pos)+1, pos-self.text.rfind('\n',0,pos)

    def fail(self, msg, pos=None):
        line,col = self.location(self.i if pos is None else pos)
        raise ConfigError(f'unable to parse config file: {msg} at line {line} column {col}')

    def skip(self, newlines=True):
        s = self.text
        while self.i < len(s):
            if s[self.i] in (' \t\r\n' if newlines else ' \t\r'): self.i += 1
            elif s[self.i] == '#':
                n = s.find('\n', self.i)
                self.i = len(s) if n < 0 else n
            else: break

    def found(self):
        if self.i >= len(self.text): return 'eof'
        c = self.text[self.i]
        return {'{':'a left brace','}':'a right brace','[':'a left bracket',']':'a right bracket',
                '=':'an equals',',':'a comma','\n':'a newline','"':'a string',"'":'a string'}.get(c,'an identifier')

    def string(self):
        q = self.text[self.i]; start = self.i; self.i += 1; result=''
        while self.i < len(self.text):
            c = self.text[self.i]; self.i += 1
            if c == q: return result
            if c == '\\' and q == '"' and self.i < len(self.text):
                c = self.text[self.i]; self.i += 1
                if c in ('u','U'):
                    n = 4 if c == 'u' else 8
                    try: result += chr(int(self.text[self.i:self.i+n],16)); self.i += n
                    except (ValueError,OverflowError): self.fail('invalid unicode escape',self.i)
                    continue
                c = {'n':'\n','t':'\t','r':'\r','b':'\b','f':'\f','"':'"','\\':'\\'}.get(c,c)
            if c == '\n': self.fail('newline in string found',self.i-1)
            result += c
        self.fail('unterminated string', start)

    def value(self):
        self.skip()
        start = self.i
        if start >= len(self.text): self.fail('expected a value, found eof')
        c = self.text[self.i]
        if c in '\"\'': return self.string(),start,'string'
        if c == '[':
            self.i += 1; values=[]
            while True:
                self.skip()
                if self.i >= len(self.text): self.fail('expected a right bracket, found eof')
                if self.text[self.i] == ']': self.i += 1; break
                values.append(self.value()); self.skip()
                if self.i < len(self.text) and self.text[self.i] == ',': self.i += 1; continue
                if self.i >= len(self.text) or self.text[self.i] != ']':
                    self.fail('expected a right bracket, found '+self.found())
            return values,start,'sequence'
        if c == '{':
            depth=1; self.i+=1
            while self.i<len(self.text) and depth:
                if self.text[self.i] in '\"\'': self.string(); continue
                if self.text[self.i]=='{': depth+=1
                if self.text[self.i]=='}': depth-=1
                self.i+=1
            return {},start,'map'
        m=re.match(r'[^\s,\]}#]+',self.text[self.i:])
        if not m: self.fail('expected a value, found '+self.found())
        v=m.group();self.i+=len(v)
        if v in ('true','false'): return v,start,'boolean'
        if re.fullmatch(r'[+-]?[0-9][0-9_]*',v): return v.replace('_',''),start,'integer'
        if re.fullmatch(r'[+-]?[0-9][0-9_.eE+-]*',v): return v,start,'float'
        if re.match(r'\d{4}-\d{2}-\d{2}',v): return v,start,'datetime'
        self.fail('expected a value, found an identifier',start)

    def parse(self):
        while True:
            self.skip()
            if self.i>=len(self.text): break
            start=self.i
            if self.text[self.i]=='[':
                end=self.text.find(']',self.i+1)
                if end<0: self.fail('expected a right bracket, found eof',len(self.text))
                self.section=self.text[self.i+1:end].strip();self.i=end+1
                if self.section in ('disabled','ignore'):
                    self.fail(f'invalid type: map, expected a sequence for key `{self.section}`',start)
                continue
            if self.text[self.i] in '\"\'': key=self.string()
            else:
                m=re.match(r'[A-Za-z0-9_.-]+',self.text[self.i:])
                if not m: self.fail('expected a table key, found '+self.found())
                key=m.group();self.i+=len(key)
            self.skip(False)
            if self.i>=len(self.text) or self.text[self.i]!='=':
                self.fail('expected an equals, found '+self.found())
            self.i+=1
            value,pos,typ=self.value()
            if not self.section and key in ('disabled','ignore'):
                if key in self.data: self.fail(f'duplicate field `{key}`',0)
                if typ!='sequence': self.type_error(value,typ,'sequence',key,pos)
                result=[]
                for val,p,t in value:
                    if t!='string': self.type_error(val,t,'string',key,p)
                    result.append(val)
                self.data[key]=result
            self.skip(False)
            if self.i<len(self.text) and self.text[self.i]!='\n':
                self.fail('expected newline, found '+self.found())
        return self.data

    def type_error(self,value,typ,expected,key,pos):
        if typ=='string': kind='string '+json.dumps(value,ensure_ascii=False)
        elif typ in ('integer','float','boolean'): kind=typ+' `'+str(value)+'`'
        else: kind=typ
        self.fail(f'invalid type: {kind}, expected a {expected} for key `{key}`',pos)


def load_config(path):
    if not os.path.exists(path): raise ConfigError('path error: No such file or directory (os error 2)')
    if os.path.isdir(path):
        path=os.path.join(path,'statix.toml')
        if not os.path.exists(path): return {'disabled':[],'ignore':[]}
    try:
        with open(path,encoding='utf-8') as f: text=f.read()
    except UnicodeError:
        raise ConfigError('path error: stream did not contain valid UTF-8')
    except OSError as e:
        raise ConfigError('path error: '+os_error(e))
    data=TomlReader(text).parse()
    return {'disabled':data.get('disabled',[]),'ignore':data.get('ignore',[])}


def os_error(e):
    return str(e.strerror)+f' (os error {e.errno})'


def check_globs(patterns):
    for p in patterns:
        raw=p
        if '[' in p and ']' not in p[p.index('['):]:
            raise ConfigError(f"error parsing ignore list `error parsing glob '{raw}': unclosed character class; missing ']'`")
        if '{' in p and '}' not in p[p.index('{'):]:
            raise ConfigError(f"error parsing ignore list `error parsing glob '{raw}': unclosed alternate group; missing '}}' (maybe escape '{{' with '[{{]'?)`")


def globmatch(path,pattern,is_dir=False):
    neg=pattern.startswith('!')
    if neg: pattern=pattern[1:]
    directory=pattern.endswith('/')
    pattern=pattern.rstrip('/')
    if directory and not is_dir: return False
    if '/' in pattern:
        path=path[2:] if path.startswith('./') else path
        pattern=pattern.lstrip('/')
        matched=fnmatch.fnmatchcase(path,pattern)
    else:
        matched=fnmatch.fnmatchcase(os.path.basename(path),pattern)
    return matched


def selected_files(target,ignore,unrestricted=False,single=False):
    if not os.path.exists(target): raise ConfigError('path error: file not found: '+target)
    if single: return [target]
    check_globs(ignore)
    def is_nix(p):
        return os.path.splitext(os.path.basename(p))[1]=='.nix'
    if not os.path.isdir(target): return [target] if is_nix(target) else []
    files=[]
    def walk(path,patterns):
        pats=list(patterns)
        if not unrestricted:
            for name in ('.gitignore','.ignore'):
                p=os.path.join(path,name)
                try:
                    with open(p,encoding='utf-8') as f:
                        pats.extend(l.strip() for l in f if l.strip() and not l.lstrip().startswith('#'))
                except (OSError,UnicodeError): pass
        try: entries=list(os.scandir(path))
        except OSError: return
        for e in entries:
            full=os.path.join(path,e.name)
            if e.name=='.git': continue
            isdir=e.is_dir(follow_symlinks=False)
            excluded=False
            for pat in pats+ignore:
                if globmatch(full,pat,isdir): excluded=not pat.startswith('!')
            if excluded: continue
            if isdir: walk(full,pats)
            elif is_nix(full): files.append(full)
    walk(target,[])
    return files
