import json
import os
import re
import sys
from pathlib import Path
from configuration import ConfigError, load_config, selected_files, os_error
from lints import analyze,fix
from render import errfmt,pretty,unified_diff

# These are UI strings, recorded from the documented commands.
with open(os.path.join(os.path.dirname(__file__),'messages.json'),encoding='utf-8') as f:
    MESSAGES=json.load(f)

COMMANDS=('check','dump','explain','fix','list','single','help')
USAGE={
    'main':'executable <SUBCOMMAND>',
    'check':'executable check [OPTIONS] [--] [TARGET]',
    'fix':'executable fix [OPTIONS] [--] [TARGET]',
    'single':'executable single [OPTIONS] --position <POSITION> [TARGET]',
    'explain':'executable explain <TARGET>',
    'list':'executable list','dump':'executable dump'}
VALUE_OPTS={'config':('CONF_PATH','c'),'format':('FORMAT','o'),'position':('POSITION','p'),'ignore':('IGNORE','i')}
FLAG_OPTS={'stdin':'s','dry-run':'d','unrestricted':'u'}

class CliError(Exception):
    def __init__(self,text): self.text=text


def fail(msg,cmd=None,hint=''):
    text='error: '+msg+'\n\n'
    if hint: text+=hint+'\n\n'
    if cmd: text+='USAGE:\n    '+USAGE[cmd]+'\n\n'
    text+='For more information try --help\n'
    raise CliError(text)


def unexpected(arg,cmd):
    hint=''
    if arg.startswith('-'):
        hint=f'\tIf you tried to supply `{arg}` as a value rather than a flag, use `-- {arg}`'
    fail(f"Found argument '{arg}' which wasn't expected, or isn't valid in this context",cmd,hint)


def invalid(opt,val,detail):
    fail(f"Invalid value for '{opt}': {detail}")


def position(value):
    parts=value.split(',')
    if len(parts)==2 and all(re.fullmatch(r'\+?\d+',p) and int(p)<=2**64-1 for p in parts):
        return tuple(int(p) for p in parts)
    invalid('--position <POSITION>',value,f'unable to parse `{value}` as line and column')


def parse(argv):
    if not argv:
        raise CliError(MESSAGES['help_main'])
    cmd=argv[0]
    if cmd in ('-h','--help'): return 'help',{'help':'main'}
    if cmd in ('-V','--version'): return 'version',{}
    if cmd=='help':
        if len(argv)==1: return 'help',{'help':'main'}
        if argv[1] in COMMANDS[:-1]: return 'help',{'help':argv[1]}
        raise CliError(f"error:  The subcommand '{argv[1]}' wasn't recognized\n\nUSAGE:\n    executable <subcommands>\n\nFor more information try --help\n")
    if cmd not in COMMANDS: unexpected(cmd,'main')
    opts={'target':None,'config':'.','format':'stderr','ignore':[],'stdin':False,
          'dry-run':False,'unrestricted':False,'position':None}
    if cmd=='check': allowed={'config','format','ignore','stdin','unrestricted'}
    elif cmd=='fix': allowed={'config','ignore','stdin','unrestricted','dry-run'}
    elif cmd=='single': allowed={'config','stdin','dry-run','position'}
    else: allowed=set()
    shorts={VALUE_OPTS[k][1]:k for k in allowed if k in VALUE_OPTS}
    shorts.update({FLAG_OPTS[k]:k for k in allowed if k in FLAG_OPTS})
    shorts['h']='help'
    seen=set();pos=[];i=1;endopts=False
    while i<len(argv):
        arg=argv[i];i+=1
        if arg=='--' and not endopts: endopts=True;continue
        if not endopts and arg.startswith('-') and arg!='-':
            flags=[]
            if arg.startswith('--'):
                v=arg[2:].split('=',1);key=v[0];inline=v[1] if len(v)>1 else None
                flags=[(key,inline,arg)]
            else:
                j=1
                while j<len(arg):
                    letter=arg[j];key=shorts.get(letter)
                    if key is None: unexpected('-'+letter,cmd)
                    j+=1
                    inline=None
                    if key in VALUE_OPTS and j<len(arg):
                        inline=arg[j:];inline=inline[1:] if inline.startswith('=') else inline;j=len(arg)
                    flags.append((key,inline,'-'+letter))
            for key,inline,display in flags:
                if key=='help': return 'help',{'help':cmd}
                if key not in allowed: unexpected(display,cmd)
                label='--'+key+((' <'+VALUE_OPTS[key][0]+('>...' if key=='ignore' else '>')) if key in VALUE_OPTS else '')
                if key in seen:
                    fail(f"The argument '{label}' was provided more than once, but cannot be used multiple times",cmd)
                seen.add(key)
                if key in VALUE_OPTS:
                    if inline is not None: val=inline
                    elif i<len(argv) and (not argv[i].startswith('-') or argv[i]=='-'):
                        val=argv[i];i+=1
                    elif i<len(argv) and argv[i].startswith('-') and argv[i] not in ('--help','-h'):
                        # An unknown flag is diagnosed before the missing value.
                        if argv[i].startswith('--'):
                            nextkey=argv[i][2:].split('=')[0]
                            if nextkey not in allowed: unexpected(argv[i],cmd)
                        elif len(argv[i])>1 and argv[i][1] not in shorts: unexpected(argv[i][:2],cmd)
                        fail(f"The argument '{label}' requires a value but none was supplied",cmd)
                    else: fail(f"The argument '{label}' requires a value but none was supplied",cmd)
                    if key=='ignore':
                        opts[key].append(val)
                        while inline is None and i<len(argv) and not argv[i].startswith('-'):
                            opts[key].append(argv[i]);i+=1
