"""Configuration and file selection, without third-party dependencies."""
import fnmatch
import json
import os
import re
from pathlib import Path

class ConfigError(Exception): pass

class TomlReader:
    def __init__(self, text):
        self.text = text
        self.i = 0
        self.section = ''
        self.data = {}

    def location(self, pos):
        return self.text.count('\n',0,pos)+1, pos-self.text.rfind('\n',0,pos)

    def fail(self, msg, pos=None):
        line,col = self.location(self.i if pos is None else pos)
        raise ConfigError(f'unable to parse config file: {msg} at line {line} column {col}')

    def skip(self, newlines=True):
        s = self.text
        while self.i < len(s):
            if s[self.i] in (' \t\r\n' if newlines else ' \t\r'): self.i += 1
            elif s[self.i] == '#':
                n = s.find('\n', self.i)
                self.i = len(s) if n < 0 else n
            else: break

    def found(self):
        if self.i >= len(self.text): return 'eof'
        c = self.text[self.i]
        return {'{':'a left brace','}':'a right brace','[':'a left bracket',']':'a right bracket',
                '=':'an equals',',':'a comma','\n':'a newline','"':'a string',"'":'a string'}.get(c,'an identifier')

    def string(self):
        q = self.text[self.i]; start = self.i; self.i += 1; result=''
        while self.i < len(self.text):
            c = self.text[self.i]; self.i += 1
            if c == q: return result
            if c == '\\' and q == '"' and self.i < len(self.text):
                c = self.text[self.i]; self.i += 1
                if c in ('u','U'):
                    n = 4 if c == 'u' else 8
                    try: result += chr(int(self.text[self.i:self.i+n],16)); self.i += n
                    except (ValueError,OverflowError): self.fail('invalid unicode escape',self.i)
                    continue
                c = {'n':'\n','t':'\t','r':'\r','b':'\b','f':'\f','"':'"','\\':'\\'}.get(c,c)
            if c == '\n': self.fail('newline in string found',self.i-1)
            result += c
        self.fail('unterminated string', start)

    def value(self):
        self.skip()
        start = self.i
        if start >= len(self.text): self.fail('expected a value, found eof')
        c = self.text[self.i]
        if c in '\"\'': return self.string(),start,'string'
        if c == '[':
            self.i += 1; values=[]
            while True:
                self.skip()
                if self.i >= len(self.text): self.fail('expected a right bracket, found eof')
                if self.text[self.i] == ']': self.i += 1; break
                values.append(self.value()); self.skip()
                if self.i < len(self.text) and self.text[self.i] == ',': self.i += 1; continue
                if self.i >= len(self.text) or self.text[self.i] != ']':
                    self.fail('expected a right bracket, found '+self.found())
            return values,start,'sequence'
        if c == '{':
            depth=1; self.i+=1
            while self.i<len(self.text) and depth:
                if self.text[self.i] in '\"\'': self.string(); continue
                if self.text[self.i]=='{': depth+=1
                if self.text[self.i]=='}': depth-=1
                self.i+=1
            return {},start,'map'
        m=re.match(r'[^\s,\]}#]+',self.text[self.i:])
        if not m: self.fail('expected a value, found '+self.found())
        v=m.group();self.i+=len(v)
        if v in ('true','false'): return v,start,'boolean'
        if re.fullmatch(r'[+-]?[0-9][0-9_]*',v): return v.replace('_',''),start,'integer'
        if re.fullmatch(r'[+-]?[0-9][0-9_.eE+-]*',v): return v,start,'float'
        if re.match(r'\d{4}-\d{2}-\d{2}',v): return v,start,'datetime'
        self.fail('expected a value, found an identifier',start)

    def parse(self):
        while True:
            self.skip()
            if self.i>=len(self.text): break
            start=self.i
            if self.text[self.i]=='[':
                end=self.text.find(']',self.i+1)
                if end<0: self.fail('expected a right bracket, found eof',len(self.text))
                self.section=self.text[self.i+1:end].strip();self.i=end+1
                if self.section in ('disabled','ignore'):
                    self.fail(f'invalid type: map, expected a sequence for key `{self.section}`',start)
                continue
            if self.text[self.i] in '\"\'': key=self.string()
            else:
                m=re.match(r'[A-Za-z0-9_.-]+',self.text[self.i:])
                if not m: self.fail('expected a table key, found '+self.found())
                key=m.group();self.i+=len(key)
            self.skip(False)
            if self.i>=len(self.text) or self.text[self.i]!='=':
                self.fail('expected an equals, found '+self.found())
            self.i+=1
            value,pos,typ=self.value()
