samples=['{\n  a = a;\n  b = pkgs.b;\n  flag = x == true;\n  f = x: double x;\n  url = https://example.org;\n}', 'let\n  a=1;\nin\nlet\n  b=2;\nin\nlet\n  c=3;\nin\n a+b+c','{\n  foo.a=1;\n  bar=1;\n  foo.b=2;\n  # comment\n\n  foo.c=3;\n}','{ foo.\n a=1; foo.\n b=2; foo.\n c=3; }', 'let\n in (\n   x\n )', '{ a = (\n x +\n y\n ); }','{inherit (\n (x)\n ) a;}','let {\n  a=1;\n  body=a;\n}','{\n  ...\n}: x','{\n  ...\n}@args: x','{\n  a\n =\n  a;\n}', 'let a=1; in let b=2; in\n x', '{\n\tfoo = foo;\n}', '{\n  "é" = 1; a=a;\n}', '"é" == true','"☃" == true']
fail=[]
for s in samples:
 for fmt in ['errfmt','stderr']:
  p=subprocess.run(['./executable','check','-s','-o',fmt],input=s,text=True,capture_output=True)
  a=errfmt(s,'<stdin>',analyze(s)) if fmt=='errfmt' else pretty(s,'<stdin>',analyze(s))
  if a!=p.stdout:
   fail.append((s,fmt,re.sub(r'\x1b\[[0-9;]*m','',p.stdout),re.sub(r'\x1b\[[0-9;]*m','',a)))
print('diffs',len(fail))
for x in fail:print(repr(x))
# single fixes with overlapping diagnostics
fail=[]
for s in ['let in (x)','{a=(x).a;}','(x)==true','let a=a; in let b=b; in (b)','{a=(x);b=b;}','x: toPath x','{inherit;}']:
 for line in [0,1,2,3]:
  for col in range(len(s)+2):
   p=subprocess.run(['./executable','single','-s','-p',f'{line},{col}'],input=s,text=True,capture_output=True)
   a=fix(s,position=(line,col))+'\n'
   if a!=p.stdout: fail.append((s,line,col,p.stdout,a))
print('single differences',len(fail))
for x in fail[:40]:print(repr(x))
json.dump(samples,open('/tmp/statix-probes/multiline.json','w'))
PY"}

